#include "dng_stage2_v0_4.h"
#include <algorithm>
#include <iomanip>
#include <iostream>
using namespace truthraw_v04;
int main(int argc,char**argv){if(argc!=2){std::cerr<<"usage: dng_stage2_v0_4_cli file.dng\n";return 2;}try{auto d=readClassicDng(argv[1]);auto s=summarizeStage2(d);std::cout<<std::setprecision(17);std::cout<<"{\n\"width\":"<<d.width<<",\"height\":"<<d.height<<",\"opcode_count\":"<<d.gainMaps.size()<<",\"black_phase\":["<<d.blackPhase[0]<<','<<d.blackPhase[1]<<','<<d.blackPhase[2]<<','<<d.blackPhase[3]<<"],\"white_level\":"<<d.whiteLevel<<",\"gain_maps\":[";for(std::size_t i=0;i<d.gainMaps.size();++i){auto&g=d.gainMaps[i];auto mm=std::minmax_element(g.values.begin(),g.values.end());if(i)std::cout<<',';std::cout<<"{\"area\":["<<g.area[0]<<','<<g.area[1]<<','<<g.area[2]<<','<<g.area[3]<<"],\"points\":["<<g.pointsV<<','<<g.pointsH<<"],\"spacing\":["<<g.spacingV<<','<<g.spacingH<<"],\"origin\":["<<g.originV<<','<<g.originH<<"],\"min\":"<<*mm.first<<",\"max\":"<<*mm.second<<"}";}std::cout<<"],\"stage2\":{\"min\":"<<s.minValue<<",\"max\":"<<s.maxValue<<",\"mean\":"<<s.mean<<",\"negative_count\":"<<s.negativeCount<<",\"over1_count\":"<<s.over1Count<<",\"clip_count\":"<<s.clipCount<<",\"total\":"<<s.total<<",\"float_bits_sum\":"<<s.floatBitsSum<<",\"float_bits_xor\":"<<s.floatBitsXor<<"},\"samples\":[";int pts[5][2]={{0,0},{0,d.width-1},{d.height/2,d.width/2},{d.height/2+1,d.width/2+1},{d.height-1,d.width-1}};for(int i=0;i<5;++i){if(i)std::cout<<',';int y=pts[i][0],x=pts[i][1];std::cout<<"{\"y\":"<<y<<",\"x\":"<<x<<",\"raw\":"<<d.raw[std::size_t(y)*d.width+x]<<",\"gain\":"<<d.gainAt(y,x)<<",\"stage2\":"<<d.stage2At(y,x)<<"}";}std::cout<<"]}\n";return 0;}catch(const std::exception&e){std::cerr<<"ERROR: "<<e.what()<<"\n";return 1;}}
